export function getMinorCardDetail(id) {
  return MINOR_ARCANA[id] ? { id, ...MINOR_ARCANA[id] } : null
}

export function getAllMinorCards() {
  return Object.entries(MINOR_ARCANA).map(([id, data]) => ({ id, ...data }))
}
